import React, { useState } from "react";
import axios from "axios";

function ArtistLogin() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://localhost:5000/registeredArtists/login", { email, password });
      alert("Login successful! Welcome " + res.data.artist.stageName);
      // Redirect to artist portfolio page, e.g.
      window.location.href = `/artists/${res.data.artist.id}`;
    } catch (err) {
      if (err.response) {
        switch (err.response.status) {
          case 403:
            alert("Your account is not approved yet. Please wait for approval.");
            break;
          case 401:
            alert("Invalid password.");
            break;
          case 404:
            alert("Artist not found.");
            break;
          default:
            alert(err.response.data.message || "Login failed.");
        }
      } else {
        alert("Server not reachable.");
      }
    }
  };

  return (
    <div>
      <h2>Artist Login</h2>
      <form onSubmit={handleLogin}>
        <div>
          <label>Email:</label>
          <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required />
        </div>
        <div>
          <label>Password:</label>
          <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} required />
        </div>
        <button type="submit">Login</button>
      </form>
    </div>
  );
}

export default ArtistLogin;
